function addTwoNumbers(l1, l2) {
    const dummy = new ListNode();
    let tail = dummy, carry = 0;
    while (l1 || l2 || carry) {
        const d1 = l1 ? l1.val : 0;
        const d2 = l2 ? l2.val : 0;
        const total = d1 + d2 + carry;
        tail.next = new ListNode(total % 10);
        tail = tail.next;
        carry = Math.floor(total / 10);
        l1 = l1 ? l1.next : null;
        l2 = l2 ? l2.next : null;
    }
    return dummy.next;
}

