public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
    ListNode dummy = new ListNode(0);
    ListNode tail = dummy;
    int carry = 0;
    while (l1 != null || l2 != null || carry > 0) {
        int d1 = (l1 != null) ? l1.val : 0;
        int d2 = (l2 != null) ? l2.val : 0;
        int total = d1 + d2 + carry;
        tail.next = new ListNode(total % 10);
        tail = tail.next;
        carry = total / 10;
        if (l1 != null) l1 = l1.next;
        if (l2 != null) l2 = l2.next;
    }
    return dummy.next;
}

code.python:
def add_two_numbers(l1, l2):
    # Decode the chain into an int, then peel digits off the sum.
    def decode(node):
        n, place = 0, 1
        while node:
            n += node.val * place
            place *= 10
            node = node.next
        return n
    total = decode(l1) + decode(l2)
    if total == 0:
        return ListNode(0)
    dummy = ListNode()
    tail = dummy
    while total:
        tail.next = ListNode(total % 10)
        tail = tail.next
        total //= 10
    return dummy.next

code.javascript:
function addTwoNumbers(l1, l2) {
    // BigInt because Number loses precision past 2^53.
    const decode = (node) => {
        let n = 0n, place = 1n;
        while (node) {
            n += BigInt(node.val) * place;
            place *= 10n;
            node = node.next;
        }
        return n;
    };
    let total = decode(l1) + decode(l2);
    if (total === 0n) return new ListNode(0);
    const dummy = new ListNode();
    let tail = dummy;
    while (total > 0n) {
        tail.next = new ListNode(Number(total % 10n));
        tail = tail.next;
        total /= 10n;
    }
    return dummy.next;
}

