def add_two_numbers(l1, l2):
    def rec(a, b, carry):
        if a is None and b is None and carry == 0:
            return None
        d1 = a.val if a else 0
        d2 = b.val if b else 0
        total = d1 + d2 + carry
        node = ListNode(total % 10)
        node.next = rec(a.next if a else None, b.next if b else None, total // 10)
        return node
    return rec(l1, l2, 0)

