function addTwoNumbers(l1, l2) {
    const rec = (a, b, carry) => {
        if (!a && !b && !carry) return null;
        const d1 = a ? a.val : 0;
        const d2 = b ? b.val : 0;
        const total = d1 + d2 + carry;
        const node = new ListNode(total % 10);
        node.next = rec(a ? a.next : null, b ? b.next : null, Math.floor(total / 10));
        return node;
    };
    return rec(l1, l2, 0);
}

