def is_balanced(root):
    def check(n):
        if n is None:
            return 0
        lh = check(n.left)
        if lh == -1:
            return -1
        rh = check(n.right)
        if rh == -1:
            return -1
        if abs(lh - rh) > 1:
            return -1
        return 1 + max(lh, rh)
    return check(root) != -1

