code.python:
def max_profit(prices):
    from functools import lru_cache
    n = len(prices)

    @lru_cache(maxsize=None)
    def dfs(i, can_buy):
        if i >= n:
            return 0
        if can_buy:
            buy = dfs(i + 1, False) - prices[i]
            skip = dfs(i + 1, True)
            return max(buy, skip)
        else:
            sell = dfs(i + 2, True) + prices[i]  # +2 enforces cooldown
            hold = dfs(i + 1, False)
            return max(sell, hold)

    return dfs(0, True)

code.javascript:
function maxProfit(prices) {
    const n = prices.length;
    const memo = new Map();
    const key = (i, b) => i * 2 + (b ? 1 : 0);
    const dfs = (i, canBuy) => {
        if (i >= n) return 0;
        const k = key(i, canBuy);
        if (memo.has(k)) return memo.get(k);
        let best;
        if (canBuy) {
            best = Math.max(dfs(i + 1, false) - prices[i], dfs(i + 1, true));
        } else {
            best = Math.max(dfs(i + 2, true) + prices[i], dfs(i + 1, false));
        }
        memo.set(k, best);
        return best;
    };
    return dfs(0, true);
}

