def max_profit_ii(prices):
    profit = 0
    i = 0
    n = len(prices)
    while i < n - 1:
        while i < n - 1 and prices[i + 1] <= prices[i]:
            i += 1
        valley = prices[i]
        while i < n - 1 and prices[i + 1] >= prices[i]:
            i += 1
        profit += prices[i] - valley
    return profit

