from functools import lru_cache

def max_coins(nums):
    arr = [1] + nums + [1]
    @lru_cache(maxsize=None)
    def solve(i, j):
        if j - i < 2:
            return 0
        best = 0
        for k in range(i + 1, j):
            gain = arr[i] * arr[k] * arr[j] + solve(i, k) + solve(k, j)
            if gain > best:
                best = gain
        return best
    return solve(0, len(arr) - 1)

