function maxCoins(nums) {
    const arr = [1, ...nums, 1];
    const n = arr.length;
    const memo = Array.from({length: n}, () => new Array(n).fill(-1));
    function solve(i, j) {
        if (j - i < 2) return 0;
        if (memo[i][j] !== -1) return memo[i][j];
        let best = 0;
        for (let k = i + 1; k < j; k++) {
            const gain = arr[i] * arr[k] * arr[j] + solve(i, k) + solve(k, j);
            if (gain > best) best = gain;
        }
        memo[i][j] = best;
        return best;
    }
    return solve(0, n - 1);
}

