def find_cheapest_price(n, flights, src, dst, k):
    import heapq
    graph = [[] for _ in range(n)]
    for u, v, w in flights:
        graph[u].append((v, w))
    # min edges used to reach a node so far; prune dominated states
    best_edges = [float('inf')] * n
    pq = [(0, src, 0)]  # (cost, node, edges_used)
    while pq:
        cost, u, edges = heapq.heappop(pq)
        if u == dst:
            return cost
        if edges >= best_edges[u] or edges > k:
            continue
        best_edges[u] = edges
        for v, w in graph[u]:
            heapq.heappush(pq, (cost + w, v, edges + 1))
    return -1

