function findCheapestPrice(n, flights, src, dst, k) {
    const graph = Array.from({length: n}, () => []);
    for (const [u, v, w] of flights) graph[u].push([v, w]);
    const bestEdges = new Array(n).fill(Infinity);
    // Tiny binary heap
    const pq = [[0, src, 0]];
    const cmp = (a, b) => a[0] - b[0];
    while (pq.length) {
        pq.sort(cmp);
        const [cost, u, edges] = pq.shift();
        if (u === dst) return cost;
        if (edges >= bestEdges[u] || edges > k) continue;
        bestEdges[u] = edges;
        for (const [v, w] of graph[u]) pq.push([cost + w, v, edges + 1]);
    }
    return -1;
}

