function climbStairs(n) {
    const memo = new Map();
    const ways = (i) => {
        if (i <= 2) return i;
        if (memo.has(i)) return memo.get(i);
        const v = ways(i - 1) + ways(i - 2);
        memo.set(i, v);
        return v;
    };
    return ways(n);
}

