private Node dfs(Node n, Map<Node, Node> map) {
    if (map.containsKey(n)) return map.get(n);
    Node clone = new Node(n.val);
    map.put(n, clone);
    for (Node nei : n.neighbors) clone.neighbors.add(dfs(nei, map));
    return clone;
}

