def combination_sum(candidates, target):
    candidates = sorted(candidates)
    dp = [[] for _ in range(target + 1)]
    dp[0] = [[]]
    for t in range(1, target + 1):
        for c in candidates:
            if c > t:
                break
            for prev in dp[t - c]:
                if not prev or prev[-1] <= c:  # canonical (non-decreasing) form
                    dp[t].append(prev + [c])
    return dp[target]

