def find_order(num_courses, prerequisites):
    graph = [[] for _ in range(num_courses)]
    for a, b in prerequisites:
        graph[b].append(a)
    color = [0] * num_courses  # 0 = white, 1 = gray, 2 = black
    order = []

    def dfs(u):
        if color[u] == 1:
            return False  # cycle
        if color[u] == 2:
            return True
        color[u] = 1
        for v in graph[u]:
            if not dfs(v):
                return False
        color[u] = 2
        order.append(u)
        return True

    for i in range(num_courses):
        if not dfs(i):
            return []
    return order[::-1]

