def decode_string(s):
    stack = []
    current = []
    count = 0
    for ch in s:
        if ch.isdigit():
            count = count * 10 + int(ch)
        elif ch == '[':
            stack.append((count, current))
            current = []
            count = 0
        elif ch == ']':
            prev_count, prev = stack.pop()
            prev.extend(current * prev_count)
            current = prev
        else:
            current.append(ch)
    return ''.join(current)

