            count = count * 10 + (ch.charCodeAt(0) - 48);
        } else if (ch === '[') {
            stack.push([count, current]);
            current = '';
            count = 0;
        } else if (ch === ']') {
            const [prevCount, prev] = stack.pop();
            current = prev + current.repeat(prevCount);
        } else {
