def decode_string(s):
    i = [0]
    def parse():
        out = []
        while i[0] < len(s) and s[i[0]] != ']':
            if s[i[0]].isdigit():
                k = 0
                while s[i[0]].isdigit():
                    k = k * 10 + int(s[i[0]])
                    i[0] += 1
                i[0] += 1  # skip '['
                inner = parse()
                i[0] += 1  # skip ']'
                out.append(inner * k)
            else:
                out.append(s[i[0]])
                i[0] += 1
        return ''.join(out)
    return parse()

