def num_decodings(s):
    from functools import lru_cache
    n = len(s)

    @lru_cache(maxsize=None)
    def decode(i):
        if i == n:
            return 1
        if s[i] == '0':
            return 0
        ways = decode(i + 1)
        if i + 1 < n and 10 <= int(s[i:i + 2]) <= 26:
            ways += decode(i + 2)
        return ways

    return decode(0)

