def diameter_of_binary_tree(root):
    def height(n):
        if n is None:
            return 0
        return 1 + max(height(n.left), height(n.right))
    best = 0
    def visit(n):
        nonlocal best
        if n is None:
            return
        local = height(n.left) + height(n.right)
        if local > best:
            best = local
        visit(n.left)
        visit(n.right)
    visit(root)
    return best

