            return ''
        for a, b in zip(w1, w2):
            if a != b:
                adj[a].add(b)
                break
    WHITE, GREY, BLACK = 0, 1, 2
    color = {c: WHITE for c in chars}
    order = []
    cycle = [False]
    def dfs(c):
        if cycle[0]: return
        if color[c] == GREY:
            cycle[0] = True; return
        if color[c] == BLACK: return
        color[c] = GREY
        for nxt in adj[c]:
            dfs(nxt)
        color[c] = BLACK
        order.append(c)
    for c in chars:
        dfs(c)
        if cycle[0]: return ''
    return ''.join(reversed(order))

