from bisect import bisect_right, insort

class DateMap:
    def __init__(self):
        self._keys = []
        self._values = {}
    def set(self, key, value):
        if key not in self._values:
            insort(self._keys, key)
        self._values[key] = value
    def get(self, key):
        idx = bisect_right(self._keys, key) - 1
        if idx < 0:
            return None
        return self._values[self._keys[idx]]

