class FirstUniqueStream:
    def __init__(self):
        self.nodes = {}
        self.rejected = set()
        self.head = self.tail = None
    def add(self, c):
        if c in self.rejected:
            return
        if c in self.nodes:
            n = self.nodes.pop(c)
            if n.prev: n.prev.next = n.next
            else: self.head = n.next
            if n.next: n.next.prev = n.prev
            else: self.tail = n.prev
            self.rejected.add(c)
        else:
            n = type('N', (), {'val': c, 'prev': self.tail, 'next': None})()
            if self.tail: self.tail.next = n
            self.tail = n
            if not self.head: self.head = n
            self.nodes[c] = n
    def first_unique(self):
        return self.head.val if self.head else ""

