code.python:
def longest_palindrome(s):
    if not s:
        return ''
    best_start = 0
    best_len = 1
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1; r += 1
        return l + 1, r - 1
    for i in range(len(s)):
        # odd-length center
        l, r = expand(i, i)
        if r - l + 1 > best_len:
            best_start, best_len = l, r - l + 1
        # even-length center
        l, r = expand(i, i + 1)
        if r - l + 1 > best_len:
            best_start, best_len = l, r - l + 1
    return s[best_start:best_start + best_len]

