        return [l + 1, r - 1];
    };
    for (let i = 0; i < s.length; i++) {
        let [l, r] = expand(i, i);
        if (r - l + 1 > bl) { bs = l; bl = r - l + 1; }
        [l, r] = expand(i, i + 1);
        if (r - l + 1 > bl) { bs = l; bl = r - l + 1; }
    }
    return s.slice(bs, bs + bl);
}

