from collections import deque

def recommendation_distance(graph, origin, dest):
    if origin == dest:
        return 0
    visited = {origin}
    q = deque([(origin, 0)])
    while q:
        node, d = q.popleft()
        for nbr in graph.get(node, []):
            if nbr in visited:
                continue
            if nbr == dest:
                return d + 1
            visited.add(nbr)
            q.append((nbr, d + 1))
    return -1

