class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def serialize(root):
    parts = []
    def go(n):
        if n is None:
            parts.append('N')
            return
        parts.append(str(n.val))
        go(n.left)
        go(n.right)
    go(root)
    return ','.join(parts)

def deserialize(s):
    it = iter(s.split(','))
    def go():
        tok = next(it)
        if tok == 'N':
            return None
        n = TreeNode(int(tok))
        n.left = go()
        n.right = go()
        return n
    return go()

def round_trip(level_order):
    root = _from_level(level_order)
    s = serialize(root)
    root2 = deserialize(s)
    return _to_level(root2)

def _from_level(arr):
    from collections import deque
    if not arr:
        return None
    root = TreeNode(arr[0])
    q = deque([root])
    i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] is not None:
            n.left = TreeNode(arr[i]); q.append(n.left)
        i += 1
        if i < len(arr) and arr[i] is not None:
            n.right = TreeNode(arr[i]); q.append(n.right)
        i += 1
    return root

def _to_level(root):
    if root is None: return []
    from collections import deque
    out = []
    q = deque([root])
    while q:
        n = q.popleft()
        if n is None:
            out.append(None)
            continue
        out.append(n.val)
        q.append(n.left)
        q.append(n.right)
    while out and out[-1] is None:
        out.pop()
    return out

