import random

def smallest_k(arr, k):
    if k <= 0:
        return []
    if k >= len(arr):
        return list(arr)
    a = list(arr)
    def partition(lo, hi):
        p = random.randint(lo, hi)
        a[p], a[hi] = a[hi], a[p]
        pivot = a[hi]
        store = lo
        for i in range(lo, hi):
            if a[i] < pivot:
                a[i], a[store] = a[store], a[i]
                store += 1
        a[store], a[hi] = a[hi], a[store]
        return store
    lo, hi = 0, len(a) - 1
    while lo < hi:
        p = partition(lo, hi)
        if p == k:
            break
        if p < k:
            lo = p + 1
        else:
            hi = p - 1
    return a[:k]

