    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
    int total = 0;
    for (int i = 0; i < lists.length; i++) {
        total += lists[i].length;
        if (lists[i].length > 0) heap.offer(new int[]{lists[i][0], i, 0});
    }
    int[] out = new int[total]; int o = 0;
    while (!heap.isEmpty()) {
        int[] t = heap.poll();
        out[o++] = t[0];
        int i = t[1], j = t[2];
        if (j + 1 < lists[i].length) heap.offer(new int[]{lists[i][j+1], i, j+1});
    }
    return out;
}

