def spell_check(words, query):
    if query in set(words):
        return [query]
    return _suggestions(words, query, max_edits=1)

def _suggestions(words, query, max_edits=1):
    out = []
    for w in words:
        if _edit_distance_at_most(query, w, max_edits):
            out.append(w)
    return out

def _edit_distance_at_most(a, b, k):
    # Quick reject on length difference
    if abs(len(a) - len(b)) > k:
        return False
    n, m = len(a), len(b)
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        cheapest = cur[0]
        for j in range(1, m + 1):
            cost = 0 if a[i-1] == b[j-1] else 1
            cur[j] = min(cur[j-1] + 1, prev[j] + 1, prev[j-1] + cost)
            cheapest = min(cheapest, cur[j])
        if cheapest > k:
            return False
        prev = cur
    return prev[m] <= k

def spell_check(words, query):
    if query in set(words):
        return [query]
    out = []
    for w in words:
        if _levenshtein(query, w) <= 1:
            out.append(w)
    return out

def _levenshtein(a, b):
    if not a: return len(b)
    if not b: return len(a)
    prev = list(range(len(b) + 1))
    for i in range(1, len(a) + 1):
        cur = [i] + [0] * len(b)
        for j in range(1, len(b) + 1):
            cost = 0 if a[i-1] == b[j-1] else 1
            cur[j] = min(cur[j-1] + 1, prev[j] + 1, prev[j-1] + cost)
        prev = cur
    return prev[-1]

