class _Node:
    __slots__ = ('children', 'count')
    def __init__(self):
        self.children = {}
        self.count = 0

def prefix_counts(words, queries):
    root = _Node()
    for w in words:
        node = root
        for ch in w:
            if ch not in node.children:
                node.children[ch] = _Node()
            node = node.children[ch]
            node.count += 1
    out = []
    for p in queries:
        node = root
        if p == '':
            out.append(len(words))
            continue
        ok = True
        for ch in p:
            if ch not in node.children:
                ok = False; break
            node = node.children[ch]
        out.append(node.count if ok else 0)
    return out

