def word_break(s, word_dict):
    words = set(word_dict)
    memo = {}
    def helper(start):
        if start == len(s):
            return []
        if start in memo:
            return memo[start]
        for end in range(start + 1, len(s) + 1):
            piece = s[start:end]
            if piece in words:
                rest = helper(end)
                if rest is not None:
                    memo[start] = [piece] + rest
                    return memo[start]
        memo[start] = None
        return None
    result = helper(0)
    return result if result else []

