    const memo = new Map();
    const helper = (start) => {
        if (start === s.length) return [];
        if (memo.has(start)) return memo.get(start);
        for (let end = start + 1; end <= s.length; end++) {
            const piece = s.slice(start, end);
            if (words.has(piece)) {
                const rest = helper(end);
                if (rest !== null) { memo.set(start, [piece, ...rest]); return memo.get(start); }
            }
        }
        memo.set(start, null);
        return null;
    };
    const result = helper(0);
    return result || [];
}

