def zigzag_level_order(level_order):
    root = _from_level(level_order)
    if root is None:
        return []
    out = []
    def go(n, depth):
        if n is None: return
        if len(out) <= depth:
            out.append([])
        if depth % 2 == 0:
            out[depth].append(n.val)
        else:
            out[depth].insert(0, n.val)
        go(n.left, depth + 1)
        go(n.right, depth + 1)
    go(root, 0)
    return out

