def decode(s):
    if s == '':
        return []
    # Split on '#;' that is NOT preceded by an unmatched '#'.
    # Easier approach: walk char-by-char.
    res, cur, i = [], [], 0
    while i < len(s):
        if s[i] == '#' and i + 1 < len(s) and s[i + 1] == '#':
            cur.append('#')
            i += 2
        elif s[i] == '#' and i + 1 < len(s) and s[i + 1] == ';':
            res.append(''.join(cur))
            cur = []
            i += 2
        else:
            cur.append(s[i])
            i += 1
    res.append(''.join(cur))
    return res

