function shortestEscapeWithOneWallRemoval(maze) {
    const rows = maze.length, cols = maze[0].length;
    const queue = [[0, 0, 0, 1]];
    const seen = new Set(['0,0,0']);
    while (queue.length) {
        const [r, c, used, dist] = queue.shift();
        if (r === rows - 1 && c === cols - 1) return dist;
        for (const [dr, dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
            const nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            const nu = used + maze[nr][nc];
            const key = `${nr},${nc},${nu}`;
            if (nu <= 1 && !seen.has(key)) { seen.add(key); queue.push([nr, nc, nu, dist + 1]); }
        }
    }
    return -1;
}

