public int evalRPN(String[] tokens) {
    Deque<Integer> stack = new ArrayDeque<>();
    for (String t : tokens) {
        switch (t) {
            case "+": case "-": case "*": case "/": {
                int b = stack.pop();
                int a = stack.pop();
                int r = 0;
                if (t.equals("+")) r = a + b;
                else if (t.equals("-")) r = a - b;
                else if (t.equals("*")) r = a * b;
                else r = a / b;  // Java int division truncates toward zero
                stack.push(r);
                break;
            }
            default:
                stack.push(Integer.parseInt(t));
        }
    }
    return stack.pop();
}

