def eval_rpn(tokens):
    ops = {'+', '-', '*', '/'}
    top = 0  # next free slot — also stack size
    buf = [0] * len(tokens)
    for t in tokens:
        if t in ops:
            b = buf[top - 1]
            a = buf[top - 2]
            top -= 2
            if t == '+':
                buf[top] = a + b
            elif t == '-':
                buf[top] = a - b
            elif t == '*':
                buf[top] = a * b
            else:
                buf[top] = int(a / b)
            top += 1
        else:
            buf[top] = int(t)
