function searchFiles(files, criteria) {
    criteria = criteria || {};
    const getExt = (name) => {
        const i = name.lastIndexOf('.');
        return i >= 0 ? name.slice(i + 1).toLowerCase() : '';
    };
    const preds = [];
    if ('name_substring' in criteria) {
        const needle = criteria.name_substring.toLowerCase();
        preds.push(f => f.name.toLowerCase().includes(needle));
    }
    if ('kind' in criteria) {
        if (criteria.kind === 'file') preds.push(f => !f.is_directory);
        else if (criteria.kind === 'directory') preds.push(f => f.is_directory);
    }
    if ('min_size' in criteria) {
        const m = criteria.min_size;
        preds.push(f => f.is_directory || f.size >= m);
    }
    if ('max_size' in criteria) {
        const m = criteria.max_size;
        preds.push(f => f.is_directory || f.size <= m);
    }
    if ('start_ts' in criteria) {
        const t = criteria.start_ts;
        preds.push(f => f.created_ts >= t);
    }
    if ('end_ts' in criteria) {
        const t = criteria.end_ts;
        preds.push(f => f.created_ts <= t);
    }
    if ('extensions' in criteria) {
        const set = new Set(criteria.extensions.map(e => e.toLowerCase().replace(/^\./, '')));
        preds.push(f => f.is_directory || set.has(getExt(f.name)));
    }
    const matches = files.filter(f => preds.every(p => p(f)));
    const sortBy = criteria.sort_by || 'name';
    const dir = criteria.sort_direction || 'asc';
    const cmp = (a, b) => {
        const get = (f) => sortBy === 'size' ? [f.size, f.name]
                          : sortBy === 'created_ts' ? [f.created_ts, f.name]
                          : sortBy === 'extension' ? [getExt(f.name), f.name]
                          : [f.name, f.name];
        const ka = get(a), kb = get(b);
        if (ka[0] < kb[0]) return -1;
        if (ka[0] > kb[0]) return 1;
        if (ka[1] < kb[1]) return -1;
        if (ka[1] > kb[1]) return 1;
        return 0;
    };
    const sorted = [...matches].sort(cmp);
    return dir === 'desc' ? sorted.reverse() : sorted;
}

