def valid_tree(n, edges):
    if len(edges) != n - 1:
        return False
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = [False] * n

    def dfs(node, parent):
        if visited[node]:
            return False
        visited[node] = True
        for nxt in adj[node]:
            if nxt == parent:
                continue
            if not dfs(nxt, node):
                return False
        return True

    if not dfs(0, -1):
        return False
    return all(visited)

