def rob(nums):
    n = len(nums)
    if n == 0:
        return 0
    if n == 1:
        return nums[0]
    if n == 2:
        return max(nums)

    from functools import lru_cache

    def best(start, end):
        # max robbable from indices [start, end) inclusive of start, exclusive of end
        @lru_cache(maxsize=None)
        def f(i):
            if i >= end:
                return 0
            return max(f(i + 1), nums[i] + f(i + 2))
        return f(start)

    return max(best(0, n - 1), best(1, n))

