def run_intcode(program):
    memory = program[:]
    ip = 0
    while memory[ip] != 99:
        opcode, a, b, dest = memory[ip:ip + 4]
        if opcode == 1:
            memory[dest] = memory[a] + memory[b]
        elif opcode == 2:
            memory[dest] = memory[a] * memory[b]
        else:
            raise ValueError(f'unknown opcode {opcode}')
        ip += 4
    return memory

