def is_interleave(s1, s2, s3):
    m, n = len(s1), len(s2)
    if m + n != len(s3):
        return False
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def go(i, j):
        if i == m and j == n:
            return True
        k = i + j
        if i < m and s1[i] == s3[k] and go(i + 1, j):
            return True
        if j < n and s2[j] == s3[k] and go(i, j + 1):
            return True
        return False
    return go(0, 0)

