        const ch = chars[i];
        let value;
        if (ch === 'X' && i === 9) value = 10;
        else if (/^[0-9]$/.test(ch)) value = Number(ch);
        else return false;
        total += value * (10 - i);
    }
    return total % 11 === 0;
}

