def can_jump(nums):
    n = len(nums)
    memo = {}

    def solve(i):
        if i >= n - 1:
            return True
        if i in memo:
            return memo[i]
        furthest = min(i + nums[i], n - 1)
        for j in range(i + 1, furthest + 1):
            if solve(j):
                memo[i] = True
                return True
