import heapq

def k_closest(points, k):
    heap = []  # max-heap via negated key
    for x, y in points:
        d2 = x * x + y * y
        if len(heap) < k:
            heapq.heappush(heap, (-d2, [x, y]))
        elif -heap[0][0] > d2:
            heapq.heapreplace(heap, (-d2, [x, y]))
    return [p for _, p in heap]

code.javascript:
// Max-heap implemented inline; key is squared distance.
function kClosest(points, k) {
    const heap = [];
    const swap = (i, j) => { [heap[i], heap[j]] = [heap[j], heap[i]]; };
    const up = (i) => {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] >= heap[i][0]) break;
            swap(i, p); i = p;
        }
    };
    const down = (i) => {
        const n = heap.length;
        while (true) {
            const l = 2*i+1, r = 2*i+2; let s = i;
            if (l < n && heap[l][0] > heap[s][0]) s = l;
            if (r < n && heap[r][0] > heap[s][0]) s = r;
            if (s === i) break;
            swap(i, s); i = s;
        }
    };
    for (const [x, y] of points) {
        const d2 = x*x + y*y;
        if (heap.length < k) { heap.push([d2, [x, y]]); up(heap.length - 1); }
        else if (heap[0][0] > d2) { heap[0] = [d2, [x, y]]; down(0); }
    }
    return heap.map(([, p]) => p);
}

