from collections import deque

def knight_min_moves(src, dest):
    if src == dest:
        return 0
    moves = [(1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)]
    sr, sc = divmod(src, 8)
    dr, dc = divmod(dest, 8)
    queue = deque([(sr, sc, 0)])
    seen = {(sr, sc)}
    while queue:
        r, c, dist = queue.popleft()
        for rr, cc in moves:
            nr, nc = r + rr, c + cc
            if not (0 <= nr < 8 and 0 <= nc < 8) or (nr, nc) in seen:
                continue
            if (nr, nc) == (dr, dc):
                return dist + 1
            seen.add((nr, nc))
            queue.append((nr, nc, dist + 1))

code.javascript:
function knightMinMoves(src, dest) {
    if (src === dest) return 0;
    const moves = [[1,2],[2,1],[2,-1],[1,-2],[-1,-2],[-2,-1],[-2,1],[-1,2]];
    const [sr, sc] = [Math.floor(src / 8), src % 8];
    const [dr, dc] = [Math.floor(dest / 8), dest % 8];
    const queue = [[sr, sc, 0]];
    const seen = new Set([sr * 8 + sc]);
    while (queue.length) {
        const [r, c, dist] = queue.shift();
        for (const [rr, cc] of moves) {
            const nr = r + rr, nc = c + cc;
            if (nr < 0 || nr >= 8 || nc < 0 || nc >= 8) continue;
            if (nr === dr && nc === dc) return dist + 1;
            const key = nr * 8 + nc;
            if (seen.has(key)) continue;
            seen.add(key);
            queue.push([nr, nc, dist + 1]);
        }
    }
}

