def largest_24_hour_time(digits):
    best = -1
    for a, b, c, d in permutations(digits):
        hours = a * 10 + b
        minutes = c * 10 + d
        if hours < 24 and minutes < 60:
            best = max(best, hours * 60 + minutes)
    if best == -1:
        return 'NOT POSSIBLE'
    return f'{best // 60:02d}:{best % 60:02d}'

