function largest24HourTime(digits) {
    let best = -1;
    const perms = (arr) => arr.length <= 1 ? [arr] : arr.flatMap((v, i) => perms([...arr.slice(0, i), ...arr.slice(i + 1)]).map(p => [v, ...p]));
    for (const [a, b, c, d] of perms(digits)) {
        const h = a * 10 + b, m = c * 10 + d;
        if (h < 24 && m < 60) best = Math.max(best, h * 60 + m);
    }
    return best === -1 ? 'NOT POSSIBLE' : String(Math.floor(best / 60)).padStart(2, '0') + ':' + String(best % 60).padStart(2, '0');
}

