def largest_rectangle_area(heights):
    def solve(lo, hi):
        if lo > hi:
            return 0
        min_idx = lo
        for k in range(lo, hi + 1):
            if heights[k] < heights[min_idx]:
                min_idx = k
        full = heights[min_idx] * (hi - lo + 1)
        return max(full, solve(lo, min_idx - 1), solve(min_idx + 1, hi))
    return solve(0, len(heights) - 1)

def largest_rectangle_area(heights):
    best = 0
    for i in range(len(heights)):
        run_min = heights[i]
        for j in range(i, len(heights)):
            run_min = min(run_min, heights[j])
            best = max(best, run_min * (j - i + 1))
    return best

