def lowest_common_ancestor(root, p, q):
    parent = {root: None}
    p_node = q_node = None
    stack = [root]
    while stack and (p_node is None or q_node is None):
        node = stack.pop()
        if node.val == p:
            p_node = node
        if node.val == q:
            q_node = node
        if node.left:
            parent[node.left] = node
            stack.append(node.left)
        if node.right:
            parent[node.right] = node
            stack.append(node.right)
    ancestors = set()
    cur = p_node
    while cur is not None:
        ancestors.add(id(cur))
        cur = parent[cur]
    cur = q_node
    while id(cur) not in ancestors:
        cur = parent[cur]
    return cur.val

