public int lowestCommonAncestor(TreeNode root, int p, int q) {
    Map<TreeNode, TreeNode> parent = new HashMap<>();
    parent.put(root, null);
    Deque<TreeNode> stack = new ArrayDeque<>();
    stack.push(root);
    TreeNode pNode = null, qNode = null;
    while (!stack.isEmpty() && (pNode == null || qNode == null)) {
        TreeNode node = stack.pop();
        if (node.val == p) pNode = node;
        if (node.val == q) qNode = node;
        if (node.left != null)  { parent.put(node.left, node);  stack.push(node.left); }
        if (node.right != null) { parent.put(node.right, node); stack.push(node.right); }
    }
    Set<TreeNode> ancestors = new HashSet<>();
    for (TreeNode cur = pNode; cur != null; cur = parent.get(cur)) ancestors.add(cur);
    TreeNode cur = qNode;
    while (!ancestors.contains(cur)) cur = parent.get(cur);
    return cur.val;
}

