class LeaderboardSystem {
    constructor() { this._players = new Map(); }
    recordPlayer(playerId, name, wins) {
        this._players.set(playerId, [name, wins]);
    }
    top(k) {
        if (k <= 0) return [];
        const ranked = [...this._players.values()].sort((a, b) => {
            if (a[1] !== b[1]) return b[1] - a[1];
            return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
        });
        return ranked.slice(0, k);
    }
}

