import bisect

class LeaderboardSystem:
    def __init__(self):
        self._players = {}    # player_id → (name, wins)
        self._sorted = []     # list of (-wins, name, player_id), kept sorted

    def record_player(self, player_id, name, wins):
        old = self._players.get(player_id)
        if old is not None:
            old_name, old_wins = old
            old_key = (-old_wins, old_name, player_id)
            i = bisect.bisect_left(self._sorted, old_key)
            if i < len(self._sorted) and self._sorted[i] == old_key:
                self._sorted.pop(i)
        self._players[player_id] = (name, wins)
        bisect.insort(self._sorted, (-wins, name, player_id))

    def top(self, k):
        if k <= 0:
            return []
        return [[name, -neg_wins] for neg_wins, name, _ in self._sorted[:k]]

