public List<String> letterCombinations(String digits) {
    List<String> result = new ArrayList<>();
    if (digits.isEmpty()) return result;
    String[] mapping = {"", "", "abc", "def", "ghi", "jkl",
                        "mno", "pqrs", "tuv", "wxyz"};
    StringBuilder path = new StringBuilder();
    backtrack(digits, 0, mapping, path, result);
    return result;
}
private void backtrack(String digits, int i, String[] mapping,
                       StringBuilder path, List<String> result) {
    if (i == digits.length()) {
        result.add(path.toString());
        return;
    }
    for (char ch : mapping[digits.charAt(i) - '0'].toCharArray()) {
        path.append(ch);
        backtrack(digits, i + 1, mapping, path, result);
        path.deleteCharAt(path.length() - 1);
    }
}

