class LFUCache {
    constructor(capacity) {
        this.cap = capacity;
        this.size = 0;
        this.minFreq = 0;
        this.keyToVal = new Map();   // key -> [value, freq]
        this.freqToKeys = new Map(); // freq -> Map(key -> true) (insertion-ordered)
    }
    _bump(key) {
        const [value, freq] = this.keyToVal.get(key);
        const bucket = this.freqToKeys.get(freq);
        bucket.delete(key);
        if (bucket.size === 0) {
            this.freqToKeys.delete(freq);
            if (this.minFreq === freq) this.minFreq += 1;
        }
        this.keyToVal.set(key, [value, freq + 1]);
        if (!this.freqToKeys.has(freq + 1)) this.freqToKeys.set(freq + 1, new Map());
        this.freqToKeys.get(freq + 1).set(key, true);
    }
    get(key) {
        if (!this.keyToVal.has(key)) return -1;
        this._bump(key);
        return this.keyToVal.get(key)[0];
    }
    put(key, value) {
        if (this.cap === 0) return;
        if (this.keyToVal.has(key)) {
            const [, freq] = this.keyToVal.get(key);
            this.keyToVal.set(key, [value, freq]);
            this._bump(key);
            return;
        }
        if (this.size === this.cap) {
            const bucket = this.freqToKeys.get(this.minFreq);
            const evictKey = bucket.keys().next().value;
            bucket.delete(evictKey);
            if (bucket.size === 0) this.freqToKeys.delete(this.minFreq);
            this.keyToVal.delete(evictKey);
            this.size -= 1;
        }
        this.keyToVal.set(key, [value, 1]);
        if (!this.freqToKeys.has(1)) this.freqToKeys.set(1, new Map());
        this.freqToKeys.get(1).set(key, true);
        this.minFreq = 1;
        this.size += 1;
    }
}

code.java:
class LFUCache {
    private final int cap;
    private int size = 0, minFreq = 0;
    private final Map<Integer, int[]> keyToVal = new HashMap<>();   // key -> {value, freq}
    private final Map<Integer, LinkedHashSet<Integer>> freqToKeys = new HashMap<>();
    public LFUCache(int capacity) { this.cap = capacity; }
    private void bump(int key) {
        int[] vf = keyToVal.get(key);
        LinkedHashSet<Integer> bucket = freqToKeys.get(vf[1]);
        bucket.remove(key);
        if (bucket.isEmpty()) {
            freqToKeys.remove(vf[1]);
            if (minFreq == vf[1]) minFreq++;
        }
        vf[1]++;
        freqToKeys.computeIfAbsent(vf[1], k -> new LinkedHashSet<>()).add(key);
    }
    public int get(int key) {
        if (!keyToVal.containsKey(key)) return -1;
        bump(key);
        return keyToVal.get(key)[0];
    }
    public void put(int key, int value) {
        if (cap == 0) return;
        if (keyToVal.containsKey(key)) {
            keyToVal.get(key)[0] = value;
            bump(key);
            return;
        }
        if (size == cap) {
            LinkedHashSet<Integer> bucket = freqToKeys.get(minFreq);
            int evict = bucket.iterator().next();
            bucket.remove(evict);
            if (bucket.isEmpty()) freqToKeys.remove(minFreq);
            keyToVal.remove(evict);
            size--;
        }
        keyToVal.put(key, new int[]{value, 1});
        freqToKeys.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
        minFreq = 1;
        size++;
    }
}

