        self.head, self.tail = _Node(), _Node()
        self.head.next = self.tail
        self.tail.prev = self.head
        self.size = 0
    def push_front(self, n):
        n.prev, n.next = self.head, self.head.next
        self.head.next.prev = n
        self.head.next = n
        self.size += 1
    def remove(self, n):
        n.prev.next = n.next; n.next.prev = n.prev
        self.size -= 1
    def pop_back(self):
        if self.size == 0: return None
        n = self.tail.prev; self.remove(n); return n

class LFUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.size = 0
        self.min_freq = 0
        self.nodes = {}      # key -> _Node
        self.buckets = {}    # freq -> _DLL
    def _touch(self, n):
        bucket = self.buckets[n.freq]
        bucket.remove(n)
        if bucket.size == 0:
            del self.buckets[n.freq]
            if self.min_freq == n.freq:
                self.min_freq += 1
        n.freq += 1
        if n.freq not in self.buckets:
            self.buckets[n.freq] = _DLL()
        self.buckets[n.freq].push_front(n)
    def get(self, key: int) -> int:
        if key not in self.nodes: return -1
        n = self.nodes[key]; self._touch(n); return n.val
    def put(self, key: int, value: int) -> None:
        if self.cap == 0: return
        if key in self.nodes:
            n = self.nodes[key]; n.val = value; self._touch(n); return
        if self.size == self.cap:
            bucket = self.buckets[self.min_freq]
            evict = bucket.pop_back()
            if bucket.size == 0: del self.buckets[self.min_freq]
            del self.nodes[evict.key]
            self.size -= 1
        n = _Node(key, value, 1)
        self.nodes[key] = n
        if 1 not in self.buckets: self.buckets[1] = _DLL()
        self.buckets[1].push_front(n)
        self.min_freq = 1
        self.size += 1

