class _Ship:
    def __init__(self, sid, length):
        self.id = sid; self.length = length; self.hits = 0
    def is_sunk(self):
        return self.hits >= self.length

class Battleship:
    SIZE = 10
    def __init__(self):
        self._grid = [[None] * self.SIZE for _ in range(self.SIZE)]
        self._ships = {}
        self._afloat = 0
    def place_ship(self, ship_id, length, x, y, direction):
        cells = []
        for i in range(length):
            cx = x + (i if direction == 'H' else 0)
            cy = y + (i if direction == 'V' else 0)
            if not (0 <= cx < self.SIZE and 0 <= cy < self.SIZE):
                return False
            if self._grid[cy][cx] is not None:
                return False
            cells.append((cx, cy))
        ship = _Ship(ship_id, length)
        self._ships[ship_id] = ship
        for cx, cy in cells:
            self._grid[cy][cx] = ship
        self._afloat += 1
        return True
    def shoot(self, x, y):
        if not (0 <= x < self.SIZE and 0 <= y < self.SIZE):
            return 'miss'
        ship = self._grid[y][x]
        if ship is None:
            return 'miss'
        self._grid[y][x] = None
        ship.hits += 1
        if ship.is_sunk():
            self._afloat -= 1
            if self._afloat == 0:
                return 'win'
            return 'sink'
        return 'hit'
    def remaining_ships(self):
        return self._afloat

