def make_change(inventory, amount):
    if amount == 0:
        return {}
    out = {}
    remaining = amount
    for denom in sorted(inventory.keys(), reverse=True):
        if remaining == 0:
            break
        avail = inventory[denom]
        use = min(remaining // denom, avail)
        if use > 0:
            out[denom] = use
            remaining -= use * denom
    if remaining != 0:
        return {}
    return out

