function makeChange(inventory, amount) {
    if (amount === 0) return {};
    const denoms = Object.keys(inventory).map(Number).sort((a, b) => b - a);
    const out = {};
    let rem = amount;
    for (const d of denoms) {
        if (rem === 0) break;
        const use = Math.min(Math.floor(rem / d), inventory[d]);
        if (use > 0) { out[d] = use; rem -= use * d; }
    }
    return rem === 0 ? out : {};
}

