def make_change(inventory, amount):
    if amount == 0:
        return {}
    INF = float('inf')
    dp = [INF] * (amount + 1)
    dp[0] = 0
    used = [None] * (amount + 1)
    denoms = sorted(inventory.keys())
    for a in range(1, amount + 1):
        for d in denoms:
            if d <= a and dp[a - d] != INF and dp[a - d] + 1 < dp[a]:
                dp[a] = dp[a - d] + 1
                used[a] = d
    if dp[amount] == INF:
        return {}
    # Reconstruct + check inventory
    out = {}
    a = amount
    while a > 0:
        d = used[a]
        out[d] = out.get(d, 0) + 1
        a -= d
    for d, c in out.items():
        if c > inventory[d]:
            return {}  # exceeds inventory; would need full bounded-knapsack
    return out

