import random
from collections import Counter

def simulate(num_dice, num_rolls, sides, seed):
    if num_rolls == 0:
        return {'mean': None, 'median': None, 'mode': None}
    rng = random.Random(seed)
    sums = []
    for _ in range(num_rolls):
        s = sum(rng.randint(1, sides) for _ in range(num_dice))
        sums.append(s)
    mean = sum(sums) / num_rolls
    sorted_sums = sorted(sums)
    n = len(sorted_sums)
    median = (sorted_sums[n // 2] if n % 2 == 1
              else (sorted_sums[n // 2 - 1] + sorted_sums[n // 2]) / 2)
    counts = Counter(sums)
    max_count = max(counts.values())
    mode = min(s for s, c in counts.items() if c == max_count)
    return {'mean': mean, 'median': median, 'mode': mode}

