def t9_lookup(digits, dictionary):
    if not digits:
        return []
    DMAP = {
        '2':'abc','3':'def','4':'ghi','5':'jkl',
        '6':'mno','7':'pqrs','8':'tuv','9':'wxyz'
    }
    # Build trie keyed on letters; track terminals.
    root = {}
    for w in dictionary:
        node = root
        for c in w:
            node = node.setdefault(c, {})
        node['$'] = w
    frontier = [(root, '')]
    for d in digits:
        nxt = []
        for node, path in frontier:
            for c in DMAP.get(d, ''):
                if c in node:
                    nxt.append((node[c], path + c))
        frontier = nxt
    return [path for node, path in frontier if '$' in node]

