def install_order(deps, target):
    if target not in deps:
        return []
    # Restrict to reachable from target
    reachable = set()
    stack = [target]
    while stack:
        p = stack.pop()
        if p in reachable: continue
        if p not in deps: return []
        reachable.add(p)
        for d in deps[p]:
            stack.append(d)
    indeg = {p: 0 for p in reachable}
    for p in reachable:
        for d in deps[p]:
            if d in reachable:
                indeg[d] += 1  # NOTE: dependency edges point FROM consumer TO provider
    # Reverse: we want to install providers first
    # Re-do with edges flipped: provider -> consumer
    indeg = {p: 0 for p in reachable}
    rev_adj = {p: [] for p in reachable}
    for p in reachable:
        for d in deps[p]:
            rev_adj[d].append(p)
            indeg[p] += 1
    from collections import deque
    q = deque([p for p in reachable if indeg[p] == 0])
    out = []
    while q:
        p = q.popleft()
        out.append(p)
        for c in rev_adj[p]:
            indeg[c] -= 1
            if indeg[c] == 0:
                q.append(c)
    return out if len(out) == len(reachable) else []

