class _Node:
    __slots__ = ('val', 'prev', 'next')
    def __init__(self, val):
        self.val = val; self.prev = self.next = None

class RecentTracks:
    def __init__(self, capacity):
        self._cap = capacity
        self._map = {}
        self._head = _Node(None); self._tail = _Node(None)
        self._head.next = self._tail; self._tail.prev = self._head
    def _unlink(self, n):
        n.prev.next = n.next; n.next.prev = n.prev
    def _insert_front(self, n):
        n.next = self._head.next; n.prev = self._head
        self._head.next.prev = n; self._head.next = n
    def play(self, track_id):
        if track_id in self._map:
            n = self._map[track_id]
            self._unlink(n)
            self._insert_front(n)
        else:
            n = _Node(track_id)
            self._map[track_id] = n
            self._insert_front(n)
            if len(self._map) > self._cap:
                old = self._tail.prev
                self._unlink(old)
                del self._map[old.val]
    def recent(self):
        out = []
        cur = self._head.next
        while cur is not self._tail:
            out.append(cur.val)
            cur = cur.next
        return out
    def count(self):
        return len(self._map)

