class _Robot:
    def __init__(self, x, y):
        self.x, self.y = x, y; self.alive = True
    def can_move(self, dx, dy): raise NotImplementedError
    def can_attack(self, tx, ty): raise NotImplementedError

class _Alpha(_Robot):
    def can_move(self, dx, dy):
        return abs(dx) + abs(dy) == 1
    def can_attack(self, tx, ty):
        return max(abs(tx - self.x), abs(ty - self.y)) == 1

class _Beta(_Robot):
    def __init__(self, x, y):
        super().__init__(x, y); self.double_left = True
    def can_move(self, dx, dy):
        return abs(dx) + abs(dy) == 1
    def can_attack(self, tx, ty):
        return abs(tx - self.x) + abs(ty - self.y) == 1

class _Gamma(_Robot):
    def can_move(self, dx, dy):
        return (abs(dx) + abs(dy)) in (1, 2) and (dx == 0 or dy == 0)
    def can_attack(self, tx, ty):
        d = abs(tx - self.x) + abs(ty - self.y)
        return d in (1, 2) and (tx == self.x or ty == self.y)

_BUILDERS = {'alpha': _Alpha, 'beta': _Beta, 'gamma': _Gamma}
_SIZE = 10

class RobotDuel:
    def __init__(self, p1_robot, p1_pos, p2_robot, p2_pos):
        self.p1 = _BUILDERS[p1_robot](*p1_pos)
        self.p2 = _BUILDERS[p2_robot](*p2_pos)
        self.current = 1
        self.actions_left = 1
        self._winner = 0
    def _own(self, p):
        return self.p1 if p == 1 else self.p2
    def _opp(self, p):
        return self.p2 if p == 1 else self.p1
    def move(self, player, dx, dy):
        if self._winner: return False
        if player != self.current: return False
        r = self._own(player)
        if not r.alive: return False
        if not r.can_move(dx, dy): return False
        nx, ny = r.x + dx, r.y + dy
        if not (0 <= nx < _SIZE and 0 <= ny < _SIZE): return False
        r.x, r.y = nx, ny
        self._end_action()
        return True
    def attack(self, player, x, y):
        if self._winner: return 'miss'
        if player != self.current: return 'miss'
        r = self._own(player)
        opp = self._opp(player)
        if not r.alive: return 'miss'
        if not r.can_attack(x, y):
            self._end_action()
            return 'miss'
        if opp.alive and opp.x == x and opp.y == y:
            opp.alive = False
            self._winner = player
            return 'win'
        self._end_action()
        return 'miss'
    def beta_double(self, player):
        if self._winner: return False
        r = self._own(player)
        if not isinstance(r, _Beta): return False
        if not r.double_left: return False
        r.double_left = False
        self.actions_left = 2
        return True
    def _end_action(self):
        self.actions_left -= 1
        if self.actions_left <= 0:
            self.current = 2 if self.current == 1 else 1
            self.actions_left = 1
    def winner(self):
        return self._winner

