import heapq

class SetWithExpiry:
    def __init__(self):
        self._exp = {}
        self._heap = []
        self._now = 0
    def _sweep(self):
        while self._heap and self._heap[0][0] <= self._now:
            t, k = heapq.heappop(self._heap)
            if self._exp.get(k) == t:
                del self._exp[k]
    def add(self, key, ttl_ms):
        e = self._now + ttl_ms
        self._exp[key] = e
        heapq.heappush(self._heap, (e, key))
    def contains(self, key):
        self._sweep()
        return key in self._exp
    def tick(self, now_ms):
        self._now = now_ms
        self._sweep()

