class Spreadsheet:
    def __init__(self):
        self._cells = {}
    def set(self, cell, value):
        if isinstance(value, str) and value.startswith('='):
            refs = value[1:].split('+')
            self._cells[cell] = ('formula', refs)
        else:
            self._cells[cell] = ('literal', value)
    def get(self, cell):
        return self._resolve(cell, set(), {})
    def _resolve(self, cell, in_progress, memo):
        if cell in memo:
            return memo[cell]
        if cell in in_progress:
            return None  # cycle
        if cell not in self._cells:
            return None
        kind, payload = self._cells[cell]
        if kind == 'literal':
            memo[cell] = payload
            return payload
        in_progress.add(cell)
        total = 0
        for ref in payload:
            v = self._resolve(ref, in_progress, memo)
            if v is None:
                in_progress.discard(cell)
                return None
            total += v
        in_progress.discard(cell)
        memo[cell] = total
        return total

