class _InsertCmd:
    def __init__(self, pos, text):
        self.pos = pos; self.text = text
    def apply(self, ed):
        ed._buf[self.pos:self.pos] = list(self.text)
    def unapply(self, ed):
        del ed._buf[self.pos:self.pos + len(self.text)]

class _DeleteCmd:
    def __init__(self, pos, count):
        self.pos = pos; self.count = count; self.removed = ''
    def apply(self, ed):
        self.removed = ''.join(ed._buf[self.pos:self.pos + self.count])
        del ed._buf[self.pos:self.pos + self.count]
    def unapply(self, ed):
        ed._buf[self.pos:self.pos] = list(self.removed)

class TextEditor:
    def __init__(self):
        self._buf = []
        self._undo = []
        self._redo = []
    def insert(self, pos, text):
        cmd = _InsertCmd(pos, text)
        cmd.apply(self)
        self._undo.append(cmd)
        self._redo.clear()
    def delete(self, pos, count):
        cmd = _DeleteCmd(pos, count)
        cmd.apply(self)
        self._undo.append(cmd)
        self._redo.clear()
    def text(self):
        return ''.join(self._buf)
    def undo(self):
        if not self._undo:
            return
        cmd = self._undo.pop()
        cmd.unapply(self)
        self._redo.append(cmd)
    def redo(self):
        if not self._redo:
            return
        cmd = self._redo.pop()
        cmd.apply(self)
        self._undo.append(cmd)

