def longest_consecutive(nums):
    parent, size = {}, {}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
    for n in set(nums):
        parent[n] = n
        size[n] = 1
        if n - 1 in parent:
            union(n, n - 1)
        if n + 1 in parent:
            union(n, n + 1)
    return max(size.values()) if size else 0

