                    if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] === 1) {
                        grid[ni][nj] = 0;
                        q.push([ni, nj]);
                    }
                }
            }
            if (area > best) best = area;
        }
    }
    return best;
}

