def max_depth(root):
    if root is None:
        return 0
    stack = [(root, 1)]
    best = 0
    while stack:
        n, d = stack.pop()
        if d > best: best = d
        if n.left:  stack.append((n.left,  d + 1))
        if n.right: stack.append((n.right, d + 1))
    return best

