def max_sub_array(nums):
    def helper(lo, hi):
        if lo == hi:
            return nums[lo]
        mid = (lo + hi) // 2
        left_best = helper(lo, mid)
        right_best = helper(mid + 1, hi)
        # Best crossing subarray: extend left from mid, right from mid+1.
        s = 0
        left_cross = float('-inf')
        for i in range(mid, lo - 1, -1):
            s += nums[i]
            left_cross = max(left_cross, s)
        s = 0
        right_cross = float('-inf')
        for i in range(mid + 1, hi + 1):
            s += nums[i]
            right_cross = max(right_cross, s)
        return max(left_best, right_best, left_cross + right_cross)
    return helper(0, len(nums) - 1)

