import heapq

def merge_k_sorted(lists):
    heap = []
    # Seed with each list's head — skip empty lists so we never pop a phantom.
    for i, lst in enumerate(lists):
        if lst:
            heapq.heappush(heap, (lst[0], i, 0))
    out = []
    while heap:
        val, i, j = heapq.heappop(heap)
        out.append(val)
        if j + 1 < len(lists[i]):
            heapq.heappush(heap, (lists[i][j + 1], i, j + 1))
    return out

code.javascript:
function mergeKSorted(lists) {
    // Tiny binary min-heap on [val, listIdx, elemIdx].
    const heap = [];
    const cmp = (a, b) => a[0] - b[0] || a[1] - b[1];
    const up = (i) => {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (cmp(heap[i], heap[p]) < 0) { [heap[i], heap[p]] = [heap[p], heap[i]]; i = p; }
            else break;
        }
    };
    const down = (i) => {
        const n = heap.length;
        while (true) {
            const l = 2 * i + 1, r = l + 1; let s = i;
            if (l < n && cmp(heap[l], heap[s]) < 0) s = l;
            if (r < n && cmp(heap[r], heap[s]) < 0) s = r;
            if (s === i) break;
            [heap[i], heap[s]] = [heap[s], heap[i]]; i = s;
        }
    };
    const push = (x) => { heap.push(x); up(heap.length - 1); };
    const pop = () => {
        const top = heap[0], last = heap.pop();
        if (heap.length) { heap[0] = last; down(0); }
        return top;
    };
    for (let i = 0; i < lists.length; i++) {
        if (lists[i].length) push([lists[i][0], i, 0]);
    }
    const out = [];
    while (heap.length) {
        const [val, i, j] = pop();
        out.push(val);
        if (j + 1 < lists[i].length) push([lists[i][j + 1], i, j + 1]);
    }
    return out;
}

code.java:
public List<Integer> mergeKSorted(List<List<Integer>> lists) {
    // (val, listIdx, elemIdx); list index breaks ties.
    PriorityQueue<int[]> pq = new PriorityQueue<>(
        (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]
    );
    for (int i = 0; i < lists.size(); i++) {
        if (!lists.get(i).isEmpty()) pq.offer(new int[]{lists.get(i).get(0), i, 0});
    }
    List<Integer> out = new ArrayList<>();
    while (!pq.isEmpty()) {
        int[] top = pq.poll();
        int val = top[0], i = top[1], j = top[2];
        out.add(val);
        if (j + 1 < lists.get(i).size()) pq.offer(new int[]{lists.get(i).get(j + 1), i, j + 1});
    }
    return out;
}

