def merge_k_sorted(lists):
    if not lists:
        return []

    def merge_two(a, b):
        out, i, j = [], 0, 0
        while i < len(a) and j < len(b):
            if a[i] <= b[j]:
                out.append(a[i]); i += 1
            else:
                out.append(b[j]); j += 1
        out.extend(a[i:])
        out.extend(b[j:])
        return out

    # Iterative pairing: stride 1, then 2, then 4, ... — log k rounds.
    step = 1
    n = len(lists)
    lists = [list(x) for x in lists]
    while step < n:
        for i in range(0, n - step, 2 * step):
            lists[i] = merge_two(lists[i], lists[i + step])
        step *= 2
    return lists[0]

