from functools import lru_cache

def min_cost_climbing_stairs(cost):
    n = len(cost)

    @lru_cache(maxsize=None)
    def reach(i):
        if i < 2:
            return cost[i]
        return cost[i] + min(reach(i - 1), reach(i - 2))

    return min(reach(n - 1), reach(n - 2))

