function minCostClimbingStairs(cost) {
    const memo = new Map();
    const reach = (i) => {
        if (i < 2) return cost[i];
        if (memo.has(i)) return memo.get(i);
        const v = cost[i] + Math.min(reach(i - 1), reach(i - 2));
        memo.set(i, v);
        return v;
    };
    const n = cost.length;
    return Math.min(reach(n - 1), reach(n - 2));
}

