public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    Integer[] memo = new Integer[n];
    return Math.min(reach(cost, n - 1, memo), reach(cost, n - 2, memo));
}

private int reach(int[] cost, int i, Integer[] memo) {
    if (i < 2) return cost[i];
    if (memo[i] != null) return memo[i];
    memo[i] = cost[i] + Math.min(reach(cost, i - 1, memo), reach(cost, i - 2, memo));
    return memo[i];
}

