code.python:
class MinStack:
    def __init__(self):
        self._stack = []  # stores deltas (val - min_at_time_of_push)
        self._min = 0
    def push(self, val):
        if not self._stack:
            self._stack.append(0)
            self._min = val
        else:
            self._stack.append(val - self._min)
            if val < self._min:
                self._min = val
    def pop(self):
        delta = self._stack.pop()
        if delta < 0:
            # popped value was the min; restore previous min
            self._min = self._min - delta
    def top(self):
        delta = self._stack[-1]
        return self._min if delta < 0 else self._min + delta
    def get_min(self):
        return self._min

