def min_window(s, t):
    if not t or len(t) > len(s):
        return ""
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    best = ""
    for i in range(len(s)):
        for j in range(i, len(s)):
            window = s[i:j + 1]
            counts = {}
            for c in window:
                counts[c] = counts.get(c, 0) + 1
            if all(counts.get(c, 0) >= n for c, n in need.items()):
                if not best or len(window) < len(best):
                    best = window
                break
    return best

