def multiply(num1, num2):
    if num1 == "0" or num2 == "0":
        return "0"
    import cmath
    a = [ord(c) - ord('0') for c in reversed(num1)]
    b = [ord(c) - ord('0') for c in reversed(num2)]
    size = 1
    while size < len(a) + len(b):
        size *= 2
    a += [0] * (size - len(a))
    b += [0] * (size - len(b))
    def fft(x, invert=False):
        n = len(x)
        if n == 1:
            return
        # iterative bit-reversal FFT (sketch — production code uses NTT)
        j = 0
        for i in range(1, n):
            bit = n >> 1
            while j & bit:
                j ^= bit
                bit >>= 1
            j ^= bit
            if i < j:
                x[i], x[j] = x[j], x[i]
        length = 2
        while length <= n:
            ang = 2 * cmath.pi / length * (-1 if invert else 1)
            wlen = cmath.exp(1j * ang)
            for i in range(0, n, length):
                w = 1
                for k in range(length // 2):
                    u = x[i + k]
                    v = x[i + k + length // 2] * w
                    x[i + k] = u + v
                    x[i + k + length // 2] = u - v
                    w *= wlen
            length <<= 1
        if invert:
            for i in range(n):
                x[i] /= n
    fa = [complex(v) for v in a]
    fb = [complex(v) for v in b]
    fft(fa)
    fft(fb)
    for i in range(size):
        fa[i] *= fb[i]
    fft(fa, invert=True)
    digits = [round(c.real) for c in fa]
    carry = 0
    for i in range(len(digits)):
        digits[i] += carry
        carry, digits[i] = digits[i] // 10, digits[i] % 10
    while carry:
        digits.append(carry % 10)
        carry //= 10
    while len(digits) > 1 and digits[-1] == 0:
        digits.pop()
    return ''.join(str(d) for d in reversed(digits))

