def count_components(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = [False] * n
    count = 0

    def dfs(node):
        stack = [node]
        while stack:
            cur = stack.pop()
            if visited[cur]:
                continue
            visited[cur] = True
            for nxt in adj[cur]:
                if not visited[nxt]:
                    stack.append(nxt)

    for i in range(n):
        if not visited[i]:
            dfs(i)
            count += 1
    return count

