class Chess:
    def __init__(self):
        self._grid = [[None] * 8 for _ in range(8)]
    def place(self, piece, color, x, y):
        self._grid[y][x] = (piece, color)
    def at(self, x, y):
        cell = self._grid[y][x]
        return list(cell) if cell else None
    def move(self, from_xy, to_xy):
        fx, fy = from_xy
        tx, ty = to_xy
        if not (0 <= fx < 8 and 0 <= fy < 8 and 0 <= tx < 8 and 0 <= ty < 8):
            return 'invalid'
        mover = self._grid[fy][fx]
        if mover is None:
            return 'invalid'
        piece, color = mover
        target = self._grid[ty][tx]
        if target is not None and target[1] == color:
            return 'invalid'
        if not self._is_legal(piece, color, fx, fy, tx, ty):
            return 'invalid'
        self._grid[ty][tx] = mover
        self._grid[fy][fx] = None
        if target is not None and target[1] != color:
            return 'capture'
        if self._side_in_check('black' if color == 'white' else 'white'):
            return 'check'
        return 'ok'
    def _is_legal(self, piece, color, fx, fy, tx, ty):
        dx, dy = tx - fx, ty - fy
        if (fx, fy) == (tx, ty):
            return False
        if piece == 'knight':
            return (abs(dx), abs(dy)) in ((1, 2), (2, 1))
        if piece == 'rook':
            return (dx == 0 or dy == 0) and self._path_clear(fx, fy, tx, ty)
        if piece == 'bishop':
            return abs(dx) == abs(dy) and self._path_clear(fx, fy, tx, ty)
        if piece == 'queen':
            return (dx == 0 or dy == 0 or abs(dx) == abs(dy)) and self._path_clear(fx, fy, tx, ty)
        if piece == 'king':
            return abs(dx) <= 1 and abs(dy) <= 1
        if piece == 'pawn':
            direction = 1 if color == 'white' else -1
            start_row = 1 if color == 'white' else 6
            tgt = self._grid[ty][tx]
            if dx == 0 and dy == direction and tgt is None:
                return True
            if dx == 0 and dy == 2 * direction and fy == start_row and tgt is None and self._grid[fy + direction][fx] is None:
                return True
            if abs(dx) == 1 and dy == direction and tgt is not None and tgt[1] != color:
                return True
            return False
        return False
    def _path_clear(self, fx, fy, tx, ty):
        sx = (tx - fx) and (1 if tx > fx else -1)
        sy = (ty - fy) and (1 if ty > fy else -1)
        x, y = fx + sx, fy + sy
        while (x, y) != (tx, ty):
            if self._grid[y][x] is not None:
                return False
            x += sx
            y += sy
        return True
    def _side_in_check(self, side):
        king_pos = None
        for y in range(8):
            for x in range(8):
                if self._grid[y][x] == ('king', side):
                    king_pos = (x, y)
        if king_pos is None:
            return False
        kx, ky = king_pos
        opp = 'black' if side == 'white' else 'white'
        for y in range(8):
            for x in range(8):
                cell = self._grid[y][x]
                if cell is None or cell[1] != opp:
                    continue
                if self._is_legal(cell[0], cell[1], x, y, kx, ky):
                    return True
        return False

