class CoffeeShop:
    _NEXT = {
        'placed':     {'preparing', 'cancelled'},
        'preparing':  {'ready', 'cancelled'},
        'ready':      {'completed'},
        'completed':  set(),
        'cancelled':  set(),
    }
    def __init__(self):
        self._menu = {}
        self._orders = {}
        self._next_id = 1
    def add_to_menu(self, name, price_cents):
        self._menu[name] = price_cents
    def place_order(self, customer_id, items):
        if any(i not in self._menu for i in items):
            return None
        oid = self._next_id; self._next_id += 1
        self._orders[oid] = {'customer': customer_id, 'items': list(items),
                              'state': 'placed'}
        return oid
    def _transition(self, oid, target):
        if oid not in self._orders: return False
        cur = self._orders[oid]['state']
        if target not in self._NEXT[cur]: return False
        self._orders[oid]['state'] = target
        return True
    def mark_ready(self, oid):
        if oid not in self._orders: return False
        # placed → preparing → ready, allow direct placed → ready too if you want
        cur = self._orders[oid]['state']
        if cur == 'placed':
            self._orders[oid]['state'] = 'preparing'
        return self._transition(oid, 'ready')
    def pickup(self, oid):
        return self._transition(oid, 'completed')
    def cancel(self, oid):
        return self._transition(oid, 'cancelled')
    def total(self, oid):
        if oid not in self._orders: return None
        return sum(self._menu[i] for i in self._orders[oid]['items'])
    def status(self, oid):
        return self._orders[oid]['state'] if oid in self._orders else None

