function pacificAtlantic(heights) {
    if (!heights.length || !heights[0].length) return [];
    const m = heights.length, n = heights[0].length;
    const pac = Array.from({length: m}, () => Array(n).fill(false));
    const atl = Array.from({length: m}, () => Array(n).fill(false));
    const dfs = (r, c, visited) => {
        visited[r][c] = true;
        for (const [dr, dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n
                && !visited[nr][nc] && heights[nr][nc] >= heights[r][c])
                dfs(nr, nc, visited);
        }
    };
    for (let c = 0; c < n; c++) { dfs(0, c, pac); dfs(m-1, c, atl); }
    for (let r = 0; r < m; r++) { dfs(r, 0, pac); dfs(r, n-1, atl); }
    const result = [];
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++)
            if (pac[r][c] && atl[r][c]) result.push([r, c]);
    return result;
}

