public List<List<Integer>> pacificAtlantic(int[][] heights) {
    List<List<Integer>> result = new ArrayList<>();
    if (heights.length == 0 || heights[0].length == 0) return result;
    int m = heights.length, n = heights[0].length;
    boolean[][] pac = new boolean[m][n];
    boolean[][] atl = new boolean[m][n];
    for (int c = 0; c < n; c++) { dfs(heights, 0, c, pac, m, n); dfs(heights, m-1, c, atl, m, n); }
    for (int r = 0; r < m; r++) { dfs(heights, r, 0, pac, m, n); dfs(heights, r, n-1, atl, m, n); }
    for (int r = 0; r < m; r++)
        for (int c = 0; c < n; c++)
            if (pac[r][c] && atl[r][c]) result.add(Arrays.asList(r, c));
    return result;
}
private void dfs(int[][] h, int r, int c, boolean[][] v, int m, int n) {
    v[r][c] = true;
    int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
    for (int[] d : dirs) {
        int nr = r + d[0], nc = c + d[1];
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && !v[nr][nc] && h[nr][nc] >= h[r][c])
            dfs(h, nr, nc, v, m, n);
    }
}

