def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    n = len(nums)
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True
    for i in range(1, n + 1):
        num = nums[i - 1]
        for s in range(1, target + 1):
            dp[i][s] = dp[i - 1][s]
            if s >= num:
                dp[i][s] = dp[i][s] or dp[i - 1][s - num]
    return dp[n][target]

def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    bits = 1  # bit 0 set: sum 0 is reachable
    for num in nums:
        bits |= bits << num
    return (bits >> target) & 1 == 1

