public double myPow(double x, int n) {
    long N = n;  // widen to dodge -INT_MIN overflow
    if (N < 0) { x = 1 / x; N = -N; }
    double result = 1.0, base = x;
    while (N > 0) {
        if ((N & 1) == 1) result *= base;
        base *= base;
        N >>= 1;
