def product_except_self(nums):
    # NOTE: violates the no-division constraint; included only for discussion.
    zeros = nums.count(0)
    if zeros >= 2:
        return [0] * len(nums)
    if zeros == 1:
        prod = 1
        for n in nums:
            if n != 0:
                prod *= n
        return [prod if n == 0 else 0 for n in nums]
    total = 1
    for n in nums:
        total *= n
    return [total // n for n in nums]

