from collections import deque

def locker_distance(m, n, lockers):
    dist = [[-1] * n for _ in range(m)]
    q = deque()
    for r, c in lockers:
        if dist[r][c] == -1:
            dist[r][c] = 0
            q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                q.append((nr, nc))
    return dist

