from collections import deque

def max_traffic(cities, event):
    if event not in cities:
        return 0
    parent = {event: None}
    q = deque([event])
    while q:
        u = q.popleft()
        for v in cities[u]['neighbors']:
            if v not in parent:
                parent[v] = u
                q.append(v)
    # For each non-event city, accumulate its pop along its path back to event
    edge_total = {}
    for c in cities:
        if c == event or c not in parent:
            continue
        cur = c
        pop = cities[c]['pop']
        while parent[cur] is not None:
            edge = (cur, parent[cur]) if cur < parent[cur] else (parent[cur], cur)
            edge_total[edge] = edge_total.get(edge, 0) + pop
            cur = parent[cur]
    return max(edge_total.values()) if edge_total else 0

