def coin_change(denominations, amount):
    memo = {0: 0}
    def f(a):
        if a in memo: return memo[a]
        best = float('inf')
        for d in denominations:
            if d <= a:
                sub = f(a - d)
                if sub != -1 and sub + 1 < best:
                    best = sub + 1
        memo[a] = -1 if best == float('inf') else best
        return memo[a]
    return f(amount)

