import re

def discount_prices(sentence, discount):
    factor = 1 - discount
    pattern = re.compile(r'\$(\d+(?:\.\d+)?)')
    def repl(m):
        val = float(m.group(1)) * factor
        s = f"{val:.2f}"
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        return f"${s}"
    return pattern.sub(repl, sentence)

