public String discountPrices(String sentence, double discount) {
    double factor = 1 - discount;
    Matcher m = Pattern.compile("\\$(\\d+(?:\\.\\d+)?)").matcher(sentence);
    StringBuffer sb = new StringBuffer();
    while (m.find()) {
        double val = Double.parseDouble(m.group(1)) * factor;
        String s = String.format("%.2f", val);
        if (s.contains(".")) s = s.replaceAll("0+$", "").replaceAll("\\.$", "");
        m.appendReplacement(sb, "\\$" + s);
    }
    m.appendTail(sb);
    return sb.toString();
}

