from collections import defaultdict

def group_isomorphic(words):
    groups = defaultdict(list)
    for w in words:
        sig = _signature(w)
        groups[sig].append(w)
    return list(groups.values())

def _signature(s):
    seen = {}
    out = []
    for c in s:
        if c not in seen:
            seen[c] = len(seen)
        out.append(seen[c])
    return tuple(out)

