            if (!(c in seen)) seen[c] = n++;
            sig.push(seen[c]);
        }
        const k = sig.join(',');
        if (!groups.has(k)) groups.set(k, []);
        groups.get(k).push(w);
    }
    return [...groups.values()];
}

