def is_same_chain(a, b):
    if a == b:
        return True
    return _reaches(a, b) or _reaches(b, a)

def _reaches(start, target, cap=30):
    cur = start
    for _ in range(cap):
        cur = _step(cur)
        if cur == target:
            return True
        if len(cur) > len(target) * 4:
            return False
    return False

def _step(s):
    if not s:
        return ''
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(str(j - i))
        out.append(s[i])
        i = j
    return ''.join(out)

