import heapq

def min_meeting_rooms(intervals):
    if not intervals:
        return 0
    sorted_intervals = sorted(intervals)
    heap = []
    best = 0
    for start, end in sorted_intervals:
        while heap and heap[0] <= start:
            heapq.heappop(heap)
        heapq.heappush(heap, end)
        best = max(best, len(heap))
    return best

code.javascript:
function minMeetingRooms(intervals) {
    if (!intervals.length) return 0;
    const sorted = [...intervals].sort((a, b) => a[0] - b[0]);
    // Inline min-heap on end times
    const heap = [];
    const swap = (i, j) => { [heap[i], heap[j]] = [heap[j], heap[i]]; };
    const up = i => { while (i > 0) { const p = (i-1)>>1; if (heap[p] <= heap[i]) break; swap(i, p); i = p; } };
    const down = i => { const n = heap.length; while (true) { const l = 2*i+1, r = 2*i+2; let s = i; if (l < n && heap[l] < heap[s]) s = l; if (r < n && heap[r] < heap[s]) s = r; if (s === i) break; swap(i, s); i = s; } };
    let best = 0;
    for (const [start, end] of sorted) {
        while (heap.length && heap[0] <= start) { swap(0, heap.length - 1); heap.pop(); down(0); }
        heap.push(end); up(heap.length - 1);
        if (heap.length > best) best = heap.length;
    }
    return best;
}

