def best_buy_sell(prices):
    if len(prices) < 2:
        return [-1, -1]
    min_idx = 0
    best = [-1, -1]
    best_profit = 0
    for i in range(1, len(prices)):
        if prices[i] < prices[min_idx]:
            min_idx = i
        else:
            profit = prices[i] - prices[min_idx]
            if profit > best_profit:
                best_profit = profit
                best = [min_idx, i]
    return best

