def find_redundant_connection(edges):
    from collections import defaultdict
    graph = defaultdict(set)

    def reachable(src, dst):
        seen = {src}
        stack = [src]
        while stack:
            node = stack.pop()
            if node == dst:
                return True
            for nxt in graph[node]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        return False

    for u, v in edges:
        if u in graph and v in graph and reachable(u, v):
            return [u, v]
        graph[u].add(v)
        graph[v].add(u)
    return []

