def is_match(s, p):
    from functools import lru_cache
    m, n = len(s), len(p)

    @lru_cache(maxsize=None)
    def dp(i, j):
        if j == n:
            return i == m
        first = i < m and p[j] in (s[i], '.')
        if j + 1 < n and p[j + 1] == '*':
            return dp(i, j + 2) or (first and dp(i + 1, j))
        return first and dp(i + 1, j + 1)

    return dp(0, 0)

