function isMatch(s, p) {
    const m = s.length, n = p.length;
    const memo = new Map();
    const dp = (i, j) => {
        const key = i * (n + 1) + j;
        if (memo.has(key)) return memo.get(key);
        let ans;
        if (j === n) ans = (i === m);
        else {
            const first = i < m && (p[j] === s[i] || p[j] === '.');
            if (j + 1 < n && p[j + 1] === '*') ans = dp(i, j + 2) || (first && dp(i + 1, j));
            else ans = first && dp(i + 1, j + 1);
        }
        memo.set(key, ans);
        return ans;
    };
    return dp(0, 0);
}

