function reverse(x) {
    const INT_MAX = 2**31 - 1;
    const INT_MIN = -(2**31);
    const sign = x < 0 ? -1 : 1;
    x = Math.abs(x);
    let result = 0;
    while (x > 0) {
        const digit = x % 10;
        x = Math.floor(x / 10);
        if (result > Math.floor(INT_MAX / 10) ||
            (result === Math.floor(INT_MAX / 10) && digit > 7)) {
            return 0;
        }
        result = result * 10 + digit;
    }
    return result * sign;
}

