def oranges_rotting(grid):
    if not grid or not grid[0]:
        return 0
    m, n = len(grid), len(grid[0])
    minutes = 0
    while True:
        changed = False
        # Mark cells that will rot this tick with a placeholder (3).
        for r in range(m):
            for c in range(n):
                if grid[r][c] != 2:
                    continue
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                        grid[nr][nc] = 3
                        changed = True
        if not changed:
            break
        # Promote placeholders to rotten.
        for r in range(m):
            for c in range(n):
                if grid[r][c] == 3:
                    grid[r][c] = 2
        minutes += 1
    # Any fresh remaining → impossible.
    for row in grid:
        if 1 in row:
            return -1
    return minutes

