from collections import deque

def max_sliding_window(nums, k):
    dq = deque()  # holds indices, values nums[dq[0]] >= nums[dq[1]] >= ...
    out = []
    for i, x in enumerate(nums):
        # 1. drop indices that fell out of the window
        if dq and dq[0] <= i - k:
            dq.popleft()
        # 2. drop tail values dominated by x
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        # 3. emit once a full window is formed
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out

code.javascript:
function maxSlidingWindow(nums, k) {
    const dq = [];  // indices
    const out = [];
    for (let i = 0; i < nums.length; i++) {
        if (dq.length && dq[0] <= i - k) dq.shift();
        while (dq.length && nums[dq[dq.length - 1]] <= nums[i]) dq.pop();
        dq.push(i);
        if (i >= k - 1) out.push(nums[dq[0]]);
    }
    return out;
}

code.java:
public int[] maxSlidingWindow(int[] nums, int k) {
    int n = nums.length;
    int[] out = new int[n - k + 1];
    java.util.Deque<Integer> dq = new java.util.ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        if (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();
        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();
        dq.offerLast(i);
        if (i >= k - 1) out[i - k + 1] = nums[dq.peekFirst()];
    }
    return out;
}

