function myAtoi(s) {
    const INT_MAX = 2 ** 31 - 1, INT_MIN = -(2 ** 31);
    let i = 0, n = s.length;
    while (i < n && s[i] === ' ') i++;
    let sign = 1;
    if (i < n && (s[i] === '+' || s[i] === '-')) {
        sign = s[i] === '-' ? -1 : 1; i++;
    }
    let result = 0;
    while (i < n && s[i] >= '0' && s[i] <= '9') {
        result = result * 10 + Number(s[i]);
        if (sign === 1 && result > INT_MAX) return INT_MAX;
        if (sign === -1 && result > -INT_MIN) return INT_MIN;
        i++;
    }
    return sign * result;
}

