code.python:
def stringify_looped_graph(graph):
    if not graph:
        return ""
    keys = list(graph.keys())
    n = len(keys)
    if n == 1:
        return keys[0]
    if n == 2:
        a, b = keys
        # Two-node 'cycle' is just A↔B; require mutual edge.
        if graph[a] != [b] and graph[a] != [b, b]: return None
        if graph[b] != [a] and graph[b] != [a, a]: return None
        return a + b

    start = keys[0]
    current = start
    prev = None
    result = []
    visited = set()

    while True:
        if current in visited:
            return None  # revisit before completion → branch / disconnect
        visited.add(current)
        result.append(current)
        conns = graph.get(current, [])
        if len(conns) != 2:
            return None
        nxt = conns[0] if conns[0] != prev else conns[1]
        if nxt not in graph:
            return None  # neighbour not in node set → malformed
        prev = current
        current = nxt
        if current == start:
            break

    if len(visited) != n:
        return None  # disconnected components
    return "".join(result)

code.javascript:
function stringifyLoopedGraph(graph) {
    if (!graph) return '';
    const keys = Object.keys(graph);
    const n = keys.length;
    if (n === 0) return '';
    if (n === 1) return keys[0];
    if (n === 2) {
        const [a, b] = keys;
        if (!graph[a].includes(b) || !graph[b].includes(a)) return null;
        return a + b;
    }

    const start = keys[0];
    let current = start;
    let prev = null;
    const result = [];
    const visited = new Set();

    while (true) {
        if (visited.has(current)) return null;
        visited.add(current);
        result.push(current);
        const conns = graph[current] || [];
        if (conns.length !== 2) return null;
        const nxt = conns[0] !== prev ? conns[0] : conns[1];
        if (!(nxt in graph)) return null;
        prev = current;
        current = nxt;
        if (current === start) break;
    }

    if (visited.size !== n) return null;
    return result.join('');
}

code.python:
def stringify_looped_graph(graph):
    if not graph: return ""
    keys = list(graph.keys())
    n = len(keys)
    if n == 1: return keys[0]
    if n == 2:
        a, b = keys
        if b not in graph.get(a, []) or a not in graph.get(b, []): return None
        return a + b

    # Pre-pass: degree, known-neighbour, symmetry.
    for node, conns in graph.items():
        if len(conns) != 2:
            return None
        for nb in conns:
            if nb not in graph or node not in graph[nb]:
                return None

    # Walk — guaranteed safe by pre-pass.
    start = keys[0]
    prev, current = None, start
    result = []
    while True:
        result.append(current)
        conns = graph[current]
        nxt = conns[0] if conns[0] != prev else conns[1]
        prev, current = current, nxt
        if current == start:
            break

    if len(result) != n:
        return None  # multiple disjoint cycles
    return "".join(result)

