function subsets(nums) {
    const result = [];
    const path = [];
    const backtrack = (i) => {
        if (i === nums.length) {
            result.push([...path]);
            return;
        }
        backtrack(i + 1);
        path.push(nums[i]);
        backtrack(i + 1);
        path.pop();
    };
    backtrack(0);
