def get_sum(a, b):
    MASK = 0xFFFFFFFF
    SIGN = 0x80000000
    while b & MASK:
        carry = ((a & b) << 1) & MASK
        a = (a ^ b) & MASK
        b = carry
    a &= MASK
    # Reinterpret as signed 32-bit
    return a if a < SIGN else ~(a ^ MASK)

