def solve(board):
    if not board or not board[0]:
        return
    m, n = len(board), len(board[0])
    BORDER = m * n
    parent = list(range(m * n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    for r in range(m):
        for c in range(n):
            if board[r][c] != 'O':
                continue
            idx = r * n + c
            if r == 0 or r == m - 1 or c == 0 or c == n - 1:
                union(idx, BORDER)
            if r + 1 < m and board[r + 1][c] == 'O':
                union(idx, (r + 1) * n + c)
            if c + 1 < n and board[r][c + 1] == 'O':
                union(idx, r * n + (c + 1))

    border_root = find(BORDER)
    for r in range(m):
        for c in range(n):
            if board[r][c] == 'O' and find(r * n + c) != border_root:
                board[r][c] = 'X'

