def find_target_sum_ways(nums, target):
    total = sum(nums)
    if abs(target) > total:
        return 0
    # offset so indices [0 .. 2*total] map to sums [-total .. +total]
    width = 2 * total + 1
    dp = [0] * width
    dp[total] = 1  # empty prefix sums to 0
    for num in nums:
        nxt = [0] * width
        for s in range(width):
            if dp[s] == 0:
                continue
            if s + num < width:
                nxt[s + num] += dp[s]
            if s - num >= 0:
                nxt[s - num] += dp[s]
        dp = nxt
    return dp[total + target] if abs(target) <= total else 0

def find_target_sum_ways(nums, target):
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def go(i, remaining):
        if i == len(nums):
            return 1 if remaining == 0 else 0
        return go(i + 1, remaining - nums[i]) + go(i + 1, remaining + nums[i])
    return go(0, target)

