import heapq
from collections import Counter

def least_interval(tasks, n):
    heap = [-c for c in Counter(tasks).values()]
    heapq.heapify(heap)
    intervals = 0
    while heap:
        used = []
        for _ in range(n + 1):
            if heap:
                used.append(heapq.heappop(heap) + 1)  # one fewer (negatives)
        for u in used:
            if u < 0:
                heapq.heappush(heap, u)
        intervals += (n + 1) if heap else len(used)
    return intervals

