function leastInterval(tasks, n) {
    const counts = new Map();
    for (const t of tasks) counts.set(t, (counts.get(t) || 0) + 1);
    let freqs = [...counts.values()];
    let intervals = 0;
    while (freqs.length) {
        freqs.sort((a, b) => b - a);
        const take = Math.min(n + 1, freqs.length);
        for (let i = 0; i < take; i++) freqs[i]--;
        freqs = freqs.filter(x => x > 0);
        intervals += freqs.length ? n + 1 : take;
    }
    return intervals;
}

