function findRiskPeriods(teamSize, threshold, vacations) {
    const events = [];
    for (const member of vacations) {
        const intervals = [...member].sort((a, b) => a[0] - b[0]);
        const merged = [];
        for (const [s, e] of intervals) {
            if (merged.length && s <= merged[merged.length - 1][1] + 1) {
                merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], e);
            } else {
                merged.push([s, e]);
            }
        }
        for (const [s, e] of merged) {
            events.push([s, 1]);
            events.push([e + 1, -1]);
        }
    }
    events.sort((a, b) => a[0] - b[0]);
    const limit = teamSize - teamSize * threshold;
    const out = [];
    let count = 0;
    let riskStart = null;
    let i = 0;
    while (i < events.length) {
        const d = events[i][0];
        while (i < events.length && events[i][0] === d) {
            count += events[i][1];
            i++;
        }
        if (count > limit && riskStart === null) riskStart = d;
        else if (count <= limit && riskStart !== null) {
            out.push([riskStart, d - 1]);
            riskStart = null;
        }
    }
    return out;
}

