def find_risk_periods(team_size, threshold, vacations):
    if not vacations or not any(vacations):
        return []
    spans = [iv for member in vacations for iv in member]
    if not spans:
        return []
    lo = min(s for s, _ in spans)
    hi = max(e for _, e in spans)
    limit = team_size - team_size * threshold
    out = []
    risk_start = None
    for d in range(lo, hi + 2):  # one past for the closing edge
        absent = sum(
            1 for member in vacations
            if any(s <= d <= e for s, e in member)
        )
        if absent > limit and risk_start is None:
            risk_start = d
        elif absent <= limit and risk_start is not None:
            out.append([risk_start, d - 1])
            risk_start = None
    return out

