        e.values.push(value);
    }
    get(key, timestamp) {
        if (!this.store.has(key)) return "";
        const { times, values } = this.store.get(key);
        let lo = 0, hi = times.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (times[mid] <= timestamp) lo = mid + 1; else hi = mid;
        }
        return lo === 0 ? "" : values[lo - 1];
    }
}

