// Min-heap implemented inline to avoid dependencies.
function topKFrequent(nums, k) {
    const counts = new Map();
    for (const n of nums) counts.set(n, (counts.get(n) || 0) + 1);
    const heap = [];
    const swap = (i, j) => { [heap[i], heap[j]] = [heap[j], heap[i]]; };
    const up = (i) => {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            swap(i, p); i = p;
        }
    };
    const down = (i) => {
        const n = heap.length;
        while (true) {
            const l = 2*i+1, r = 2*i+2;
            let s = i;
            if (l < n && heap[l][0] < heap[s][0]) s = l;
            if (r < n && heap[r][0] < heap[s][0]) s = r;
            if (s === i) break;
            swap(i, s); i = s;
        }
    };
    for (const [val, freq] of counts) {
        heap.push([freq, val]); up(heap.length - 1);
        if (heap.length > k) { swap(0, heap.length - 1); heap.pop(); down(0); }
    }
    return heap.map(([_, v]) => v);
}

