def urlify(chars, true_length):
    space_count = sum(1 for i in range(true_length) if chars[i] == ' ')
    write = true_length + space_count * 2 - 1
    for read in range(true_length - 1, -1, -1):
        if chars[read] == ' ':
            chars[write - 2:write + 1] = ['%', '2', '0']
            write -= 3
        else:
            chars[write] = chars[read]
            write -= 1
    return ''.join(chars[:true_length + space_count * 2])

code.javascript:
function urlify(chars, trueLength) {
    let spaces = 0;
    for (let i = 0; i < trueLength; i++) if (chars[i] === ' ') spaces++;
    let write = trueLength + spaces * 2 - 1;
    for (let read = trueLength - 1; read >= 0; read--) {
        if (chars[read] === ' ') {
            chars[write--] = '0';
            chars[write--] = '2';
            chars[write--] = '%';
        } else {
            chars[write--] = chars[read];
        }
    }
    return chars.slice(0, trueLength + spaces * 2).join('');
}

