    for r in range(9):
        for c in range(9):
            d = board[r][c]
            if d == '.':
                continue
            b = (r // 3) * 3 + (c // 3)
            keys = ((d, 'r', r), (d, 'c', c), (d, 'b', b))
            for k in keys:
                if k in seen:
                    return False
                seen.add(k)
    return True

