            if (d === '.') continue;
            const b = Math.floor(r / 3) * 3 + Math.floor(c / 3);
            const keys = [`${d} r${r}`, `${d} c${c}`, `${d} b${b}`];
            for (const k of keys) {
                if (seen.has(k)) return false;
                seen.add(k);
            }
        }
    }
    return true;
}

