function ladderLength(beginWord, endWord, wordList) {
    const wordSet = new Set(wordList);
    if (!wordSet.has(endWord)) return 0;
    const M = beginWord.length;
    const patternMap = new Map();
    for (const word of wordSet) {
        for (let i = 0; i < M; i++) {
            const p = word.slice(0, i) + '*' + word.slice(i + 1);
            if (!patternMap.has(p)) patternMap.set(p, []);
            patternMap.get(p).push(word);
        }
    }
    const queue = [[beginWord, 1]];
    const visited = new Set([beginWord]);
    while (queue.length) {
        const [word, steps] = queue.shift();
        for (let i = 0; i < M; i++) {
            const p = word.slice(0, i) + '*' + word.slice(i + 1);
            for (const nxt of (patternMap.get(p) || [])) {
                if (nxt === endWord) return steps + 1;
                if (!visited.has(nxt)) {
                    visited.add(nxt);
                    queue.push([nxt, steps + 1]);
                }
            }
            patternMap.set(p, []);
        }
    }
    return 0;
}

