public int ladderLength(String beginWord, String endWord, List<String> wordList) {
    Set<String> wordSet = new HashSet<>(wordList);
    if (!wordSet.contains(endWord)) return 0;
    int M = beginWord.length();
    Map<String, List<String>> patternMap = new HashMap<>();
    for (String word : wordSet) {
        for (int i = 0; i < M; i++) {
            String p = word.substring(0, i) + '*' + word.substring(i + 1);
            patternMap.computeIfAbsent(p, k -> new ArrayList<>()).add(word);
        }
    }
    Deque<String[]> queue = new ArrayDeque<>();
    queue.offer(new String[]{beginWord, "1"});
    Set<String> visited = new HashSet<>();
    visited.add(beginWord);
    while (!queue.isEmpty()) {
        String[] cur = queue.poll();
        String word = cur[0];
        int steps = Integer.parseInt(cur[1]);
        for (int i = 0; i < M; i++) {
            String p = word.substring(0, i) + '*' + word.substring(i + 1);
            for (String nxt : patternMap.getOrDefault(p, Collections.emptyList())) {
                if (nxt.equals(endWord)) return steps + 1;
                if (!visited.contains(nxt)) {
                    visited.add(nxt);
                    queue.offer(new String[]{nxt, String.valueOf(steps + 1)});
                }
            }
            patternMap.put(p, new ArrayList<>());
        }
    }
    return 0;
}

