def find_words(board, words):
    # Build trie: each node is a dict; '$' key holds the full word at terminals.
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node['$'] = w

    rows, cols = len(board), len(board[0])
    found = []

    def dfs(r, c, node):
        ch = board[r][c]
        nxt = node.get(ch)
        if nxt is None:
            return
        word = nxt.pop('$', None)
        if word is not None:
            found.append(word)
        board[r][c] = '#'
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] != '#':
                dfs(nr, nc, nxt)
        board[r][c] = ch
        # Prune dead branches so future cells skip them.
        if not nxt:
            node.pop(ch, None)

    for r in range(rows):
        for c in range(cols):
            dfs(r, c, root)
    return found

