import java.util.*;
public List<String> findWords(char[][] board, String[] words) {
    // Trie node: 26 children + word field at terminals.
    class Node { Node[] kids = new Node[26]; String word; }
    Node root = new Node();
    for (String w : words) {
        Node n = root;
        for (char c : w.toCharArray()) {
            int i = c - 'a';
            if (n.kids[i] == null) n.kids[i] = new Node();
            n = n.kids[i];
        }
        n.word = w;
    }
    List<String> out = new ArrayList<>();
    int rows = board.length, cols = board[0].length;
    int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
    // Recursive DFS via inner method emulation.
    dfs(board, rows, cols, 0, 0, root, out, dirs); // placeholder; see helper.
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            dfs(board, rows, cols, r, c, root, out, dirs);
    return out;
}
// Helper assumes the Node class above is in scope (factor out as needed).

