def find_words(board, words):
    rows, cols = len(board), len(board[0])

    def exist(word):
        def dfs(r, c, i):
            if i == len(word):
                return True
            if r < 0 or r >= rows or c < 0 or c >= cols or board[r][c] != word[i]:
                return False
            saved = board[r][c]
            board[r][c] = '#'
            ok = (dfs(r+1, c, i+1) or dfs(r-1, c, i+1)
                  or dfs(r, c+1, i+1) or dfs(r, c-1, i+1))
            board[r][c] = saved
            return ok
        for r in range(rows):
            for c in range(cols):
                if dfs(r, c, 0):
                    return True
        return False

    return [w for w in words if exist(w)]

