function zigzagConvert(s, numRows) {
    if (numRows === 1 || numRows >= s.length) return s;
    const rows = Array.from({ length: numRows }, () => '');
    let row = 0, step = 1;
    for (const ch of s) {
        rows[row] += ch;
        if (row === 0) step = 1;
        else if (row === numRows - 1) step = -1;
        row += step;
    }
    return rows.join('');
}
